export default function TextPreview() {
  const [value, setValue] = useState('');
  return <div>
    <textarea value={value} onChange={(event) => setValue(event.target.value)} />
    <p>{value ? value.slice(0, 20) + (value.length > 20 ? '…' : '') : '미리보기 없음'}</p>
  </div>;
}]

