export default function FaqToggle() {
  const [open, setOpen] = useState(false);
  return <section>
    <p>배송은 얼마나 걸리나요?</p>
    <button aria-expanded={open} onClick={() => setOpen(!open)}>
      {open ? '답변 닫기' : '답변 보기'}
    </button>
    {open && <p>배송은 2~3일 걸립니다.</p>}
